-- Seed da CBHPO 2024 (CFO/CNCC). Valores oficiais imutáveis.
-- Re-aplicado via UPSERT quando atualizar referência. Nunca toca em procedimentos.valor_atual.

ON CONFLICT(codigo_cbhpo) DO UPDATE SET
  nome_oficial  = excluded.nome_oficial,
  categoria     = excluded.categoria,
  valor_oficial = excluded.valor_oficial,
  versao        = excluded.versao,
  fonte         = excluded.fonte,
  atualizado_em = datetime('now', 'localtime');
